<!doctype html>
<html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#173f40;font-size:12px}.header{border-bottom:3px solid #e8b949;padding-bottom:16px}.logo{width:120px}h1{float:right;margin:10px 0}table{width:100%;border-collapse:collapse;margin-top:25px}th,td{padding:10px;border-bottom:1px solid #dfe6df}th{background:#edf3e9;text-align:left}.money{text-align:right}.total{font-size:16px;background:#f7f3df}.footer{margin-top:30px;color:#61716e;font-size:10px}</style></head>
<body><div class="header"><img class="logo" src="{{public_path('images/landpay-logo.png')}}"><h1>Payment Receipt</h1></div>
<p><strong>Payment date:</strong> {{$payment->received_date->format('F j, Y')}}<br><strong>Plan:</strong> {{$payment->financialTransaction->paymentPlan->plan_number}} &mdash; {{$payment->financialTransaction->paymentPlan->title}}<br><strong>Method:</strong> {{str($payment->payment_method->value)->replace('_',' ')->title()}}<br><strong>Reference:</strong> {{$payment->external_reference ?: $payment->financialTransaction->uuid}}</p>
<table><thead><tr><th>Payment</th><th class="money">Amount</th></tr></thead><tbody><tr class="total"><td><strong>Payment received</strong></td><td class="money"><strong>{{\App\Support\Money::format($payment->gross_amount)}}</strong></td></tr></tbody></table>
<div class="footer">{{\App\Models\AppSetting::valueFor('company_name',config('app.name','LandPay'))}} &mdash; {{\App\Models\AppSetting::valueFor('company_email','')}}</div></body></html>
